package in.recallradar;
import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service @Transactional class IncidentService {private final IncidentRepository incidents;private final LotQuarantineRepository quarantines;private final CorrectiveActionRepository actions;private final InventoryLotRepository lots;private final IngredientRepository ingredients;private final TenantService tenants;private final AuditService audit;
 IncidentService(IncidentRepository i,LotQuarantineRepository q,CorrectiveActionRepository a,InventoryLotRepository l,IngredientRepository ing,TenantService t,AuditService au){incidents=i;quarantines=q;actions=a;lots=l;ingredients=ing;tenants=t;audit=au;}
 List<IncidentResponse> list(Membership m){return incidents.findByOrganizationIdOrderByCreatedAtDesc(m.organizationId).stream().map(x->response(m,x)).toList();}
 IncidentResponse create(Membership m,IncidentCreateRequest request){edit(m);var incident=incidents.save(new Incident(m.organizationId,request.title().trim(),request.severity(),m.userId));for(var lotId:new LinkedHashSet<>(request.lotIds())){lot(m,lotId);quarantines.save(new LotQuarantine(incident.id,lotId,blank(request.quarantineReason())));}audit.record(m,"INCIDENT_CREATED","INCIDENT",incident.id,incident.title);return response(m,incident);}
 IncidentResponse status(Membership m,UUID id,IncidentStatusRequest request){edit(m);var incident=incident(m,id);incident.status=request.status();audit.record(m,"INCIDENT_STATUS_UPDATED","INCIDENT",incident.id,request.status().name());return response(m,incident);}
 IncidentResponse release(Membership m,UUID incidentId,UUID quarantineId){edit(m);var incident=incident(m,incidentId);var quarantine=quarantines.findByIdAndIncidentId(quarantineId,incident.id).orElseThrow(()->missing("Quarantine"));if(!quarantine.active)throw new ResponseStatusException(HttpStatus.CONFLICT,"This batch is already released.");quarantine.release();audit.record(m,"LOT_QUARANTINE_RELEASED","INVENTORY_LOT",quarantine.lotId,"Released from incident "+incident.title);return response(m,incident);}
 IncidentResponse addAction(Membership m,UUID incidentId,CorrectiveActionRequest request){edit(m);var incident=incident(m,incidentId);actions.save(new CorrectiveAction(incident.id,request.description().trim()));audit.record(m,"CORRECTIVE_ACTION_ADDED","INCIDENT",incident.id,request.description().trim());return response(m,incident);}
 IncidentResponse completeAction(Membership m,UUID incidentId,UUID actionId){edit(m);var incident=incident(m,incidentId);var action=actions.findByIdAndIncidentId(actionId,incident.id).orElseThrow(()->missing("Corrective action"));if(!action.completed)action.complete();audit.record(m,"CORRECTIVE_ACTION_COMPLETED","INCIDENT",incident.id,action.description);return response(m,incident);}
 private IncidentResponse response(Membership m,Incident incident){var qs=quarantines.findByIncidentIdOrderByCreatedAt(incident.id).stream().map(q->{var lot=lot(m,q.lotId);var ingredient=ingredients.findByIdAndOrganizationId(lot.ingredientId,m.organizationId).orElseThrow();return new QuarantineResponse(q.id.toString(),lot.id.toString(),ingredient.name,lot.supplierBatchNumber,q.active,q.reason,q.createdAt,q.releasedAt);}).toList();var as=actions.findByIncidentIdOrderByCreatedAt(incident.id).stream().map(a->new CorrectiveActionResponse(a.id.toString(),a.description,a.completed,a.createdAt,a.completedAt)).toList();return new IncidentResponse(incident.id.toString(),incident.title,incident.status,incident.severity,incident.createdAt,qs,as);}
 private Incident incident(Membership m,UUID id){return incidents.findByIdAndOrganizationId(id,m.organizationId).orElseThrow(()->missing("Incident"));}private InventoryLot lot(Membership m,UUID id){return lots.findByIdAndOrganizationId(id,m.organizationId).orElseThrow(()->missing("Batch"));}private void edit(Membership m){tenants.requireMasterDataEditor(m);}private String blank(String s){return s==null||s.isBlank()?null:s.trim();}private ResponseStatusException missing(String n){return new ResponseStatusException(HttpStatus.NOT_FOUND,n+" not found.");}}
